const html = require('fs').readFileSync('index.html','utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
const noop = () => {};
const ctxStub = new Proxy({}, { get: (t,k) => (k==='createRadialGradient' ? (()=>({addColorStop:noop})) : noop), set: () => true });
global.document = { getElementById: () => ({ width:900, height:900, getContext: () => ctxStub }) };
global.window = {};
global.performance = { now: () => 0 };
global.requestAnimationFrame = noop;
eval(m[1]);
const B = global.window.__bench;

const TAU = Math.PI*2;
function polyPts(st){ const a=st.t*(TAU/7), n=9, pts=[];
  for(let i=0;i<n;i++){const th=a+i*TAU/n; pts.push([st.poly.cx+Math.cos(th)*st.poly.radius, st.poly.cy+Math.sin(th)*st.poly.radius]);} return pts;}
function minEdgeDist(px,py,pts,st){ // distância mínima ao contorno
  let bd=1e18;
  for(let i=0;i<pts.length;i++){const A=pts[i],B2=pts[(i+1)%pts.length];
    const ex=B2[0]-A[0],ey=B2[1]-A[1],l2=ex*ex+ey*ey;
    let s=Math.max(0,Math.min(1,((px-A[0])*ex+(py-A[1])*ey)/l2));
    const qx=A[0]+ex*s,qy=A[1]+ey*s; const d=(px-qx)**2+(py-qy)**2; if(d<bd)bd=d;}
  return Math.sqrt(bd);}

let maxPen=0, maxOv=0;
for(let k=1;k<=1800;k++){   // 30 s a 60Hz
  const s = B.step(1/60);
  const pts = polyPts(s);
  for(const b of s.balls){
    const d = minEdgeDist(b.x,b.y,pts,s);
    const pen = b.r - d;
    if(pen>maxPen) maxPen=pen;
    if(pen > 0.5) throw new Error('OUTSIDE k='+k+' id='+b.id+' pen='+pen.toFixed(3));
  }
  for(let i=0;i<s.balls.length;i++) for(let j=i+1;j<s.balls.length;j++){
    const a=s.balls[i],b=s.balls[j];
    const d=Math.hypot(a.x-b.x,a.y-b.y)-28;
    if(d>maxOv)maxOv=d;
    if(d < -2.0) throw new Error('OVERLAP k='+k+' '+a.id+' '+b.id+' d='+d.toFixed(3));
  }
}
const st = B.getState();
console.log('t =', st.t.toFixed(2), ' angle =', (st.poly.angle*180/Math.PI).toFixed(1)+'deg' , ' period check:', (st.t % 7).toFixed(2));
console.log('max wall penetration during 30s:', maxPen.toFixed(4), 'px');
console.log('max ball overlap during 30s:', maxOv.toFixed(4), 'px (neg=touch)');
console.log('energy sample ball0:', JSON.stringify(st.balls[0]).slice(0,120));
console.log('ALL CHECKS PASSED (30 s)');
"

